 private FrameworkElement Dashboard(){var root=Column();var patients=store.All<Patient>("patients").Where(x=>!x.Deleted).ToList();var today=patients.Where(x=>x.Date==Today).ToList();var todayExp=store.All<Expense>("expenses").Where(x=>x.Date==Today).Sum(x=>x.Amount);
  var grid=new UniformGrid{Columns=4,Margin=new Thickness(0,0,0,12)};
  foreach(var (heading,value,sub) in new[]{("Today's Gross Billing",today.Sum(x=>x.Subtotal).ToString("N0"),"Before discounts"),("Cash Remaining Today",(today.Sum(x=>x.Received)-todayExp).ToString("N0"),"Received less expenses"),("Outstanding Balance",patients.Sum(x=>x.Balance).ToString("N0"),"All unpaid visits"),("Patients Today",today.Count.ToString(),"Registered visits")}){var p=Column();p.Children.Add(Text(heading,11,true));p.Children.Add(Text(heading=="Patients Today"?value:"Rs "+value,26,true));p.Children.Add(Text(sub,10));var card=Card(p);card.Margin=new Thickness(0,0,10,10);grid.Children.Add(card);}root.Children.Add(grid);
  var chart=Column();var pick=Row();pick.Children.Add(Text("Modality performance",17,true));var period=Select(pick,"Period",new[]{"Today","7 Days","This Month"},"7 Days");var metric=Select(pick,"Metric",new[]{"Examinations","Received earnings"},"Examinations");chart.Children.Add(pick);var canvas=new Canvas{Height=265,MinWidth=680,ClipToBounds=false};chart.Children.Add(canvas);var legend=Row();foreach(var (name,color) in new[]{("CT Scan","#3D8CFA"),("X-Ray","#09B6BA"),("Ultrasound","#977BF6")}){var b=Text("●  "+name,11);b.Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString(color)!);b.Margin=new Thickness(0,2,25,4);legend.Children.Add(b);}chart.Children.Add(legend);root.Children.Add(Card(chart));void redraw()=>DrawChart(canvas,period.SelectedItem?.ToString()??"7 Days",metric.SelectedItem?.ToString()??"Examinations");period.SelectionChanged+=(_,_)=>redraw();metric.SelectionChanged+=(_,_)=>redraw();canvas.Loaded+=(_,_)=>redraw();canvas.SizeChanged+=(_,_)=>redraw();
  root.Children.Add(Card(GridView(patients.OrderByDescending(x=>x.Date).Take(9).Select(x=>new{x.Receipt,x.Date,x.Name,Tests=string.Join(", ",x.Tests.Select(t=>t.Name)),x.Net,x.Received,x.Balance}).ToList(),310),"Recent patients"));return root;
 }
 private void DrawChart(Canvas canvas,string period,string metric){if(canvas.ActualWidth<100)return;canvas.Children.Clear();var p=store.All<Patient>("patients").Where(x=>!x.Deleted);string start=period switch{"Today"=>Today,"7 Days"=>DateTime.Today.AddDays(-6).ToString("yyyy-MM-dd"),_=>DateTime.Today.ToString("yyyy-MM")+"-01"};p=p.Where(x=>string.CompareOrdinal(x.Date,start)>=0);
  var categories=new[]{"CT","X-Ray","Ultrasound"};var nums=new double[3];foreach(var x in p){var denom=x.Tests.Sum(t=>t.Price);foreach(var t in x.Tests){var cat=LegacyImporter.Modality(t.Name);int i=Array.IndexOf(categories,cat);if(i<0)continue;nums[i]+=metric=="Examinations"?1:(double)(denom>0?x.Received*t.Price/denom:0);}}
  double max=Math.Max(1,nums.Max()),width=Math.Max(canvas.ActualWidth,690),axis=228,usable=180;var colors=new[]{("#3B8DF5","#245FA9","#8CBFFF"),("#00B4B7","#04777C","#66DBD8"),("#9879F1","#6444BA","#C7B9FF")};
  for(int i=0;i<4;i++){double y=axis-i*usable/3;var rule=new Line{X1=0,X2=width-24,Y1=y,Y2=y,Stroke=new SolidColorBrush(Color.FromRgb(214,225,239)),StrokeThickness=1,Opacity=.45};canvas.Children.Add(rule);var tag=Text(metric=="Examinations"?Math.Round(max*i/3).ToString():Math.Round(max*i/3).ToString("N0"),9);Canvas.SetLeft(tag,2);Canvas.SetTop(tag,y-19);canvas.Children.Add(tag);}
  for(int i=0;i<3;i++){double x=width*(i+1)/4-36,h=nums[i]/max*usable; if(h<1)h=1;var left=(Brush)new BrushConverter().ConvertFromString(colors[i].Item1)!;var side=(Brush)new BrushConverter().ConvertFromString(colors[i].Item2)!;var top=(Brush)new BrushConverter().ConvertFromString(colors[i].Item3)!;
   var bar=new Canvas{Width=80,Height=h+20};bar.RenderTransformOrigin=new Point(.5,1);
   var front=new Rectangle{Width=56,Height=h,Fill=left,RadiusX=4,RadiusY=4};Canvas.SetLeft(front,1);Canvas.SetTop(front,18);bar.Children.Add(front);
   var sideFace=new Polygon{Points=new PointCollection{new(57,18),new(75,1),new(75,h+1),new(57,h+18)},Fill=side};bar.Children.Add(sideFace);
   var cap=new Polygon{Points=new PointCollection{new(1,18),new(18,1),new(75,1),new(57,18)},Fill=top};bar.Children.Add(cap);
   var tip=$"{categories[i]} • {period}\n{metric}: {(metric=="Examinations"?nums[i].ToString("N0"):"Rs "+nums[i].ToString("N0"))}";ToolTipService.SetToolTip(bar,tip);bar.MouseLeftButtonUp+=(_,_)=>Info(tip);
   Canvas.SetLeft(bar,x);Canvas.SetTop(bar,axis-h-18);canvas.Children.Add(bar);
   var anim=new ScaleTransform(1,0,0,0);bar.RenderTransform=anim;var scale=new DoubleAnimation(0,1,TimeSpan.FromMilliseconds(700+i*130)){EasingFunction=new CubicEase{EasingMode=EasingMode.EaseOut}};anim.BeginAnimation(ScaleTransform.ScaleYProperty,scale);
   var label=Text(categories[i],12,true);Canvas.SetLeft(label,x-5);Canvas.SetTop(label,axis+11);canvas.Children.Add(label);
  }
 }
 private FrameworkElement Reception(Patient? editing=null){var root=Column();var main=new UniformGrid{Columns=2};var left=Column();var right=Column();main.Children.Add(Card(left,"Patient details"));main.Children.Add(Card(right,"Tests & billing"));root.Children.Add(main);
  var name=Field(left,"Patient name *",editing?.Name??"");var phone=Field(left,"Mobile / WhatsApp",editing?.Phone??"");var age=Field(left,"Age",editing?.Age??"");var gender=Select(left,"Gender",new[]{"Not specified","Male","Female","Other"},editing?.Gender??"Not specified");var mr=Field(left,"CT MR Number (mandatory for CT)",editing?.Mr??"");var refdoc=Select(left,"Referring Doctor",new[]{"Not specified"}.Concat(store.All<Doctor>("doctors").Where(d=>d.Group=="Referring").Select(d=>d.Name)),editing?.ReferringDoctor??"Not specified");var perf=Select(left,"Performing Doctor",new[]{"Not specified"}.Concat(store.All<Doctor>("doctors").Where(d=>d.Group=="Performing").Select(d=>d.Name)),editing?.PerformingDoctor??"Not specified");var clinical=Field(left,"Clinical notes",editing?.Notes??"",2000);
  var search=Field(right,"Search radiology test");var candidates=new ListBox{Height=105,DisplayMemberPath="Name",Margin=new Thickness(0,0,0,8)};right.Children.Add(candidates);var allTests=store.All<TestDefinition>("tests").OrderBy(t=>t.Name).ToList();void filter(){candidates.ItemsSource=allTests.Where(x=>x.Name.Contains(search.Text,StringComparison.OrdinalIgnoreCase)).Take(65).ToList();}search.TextChanged+=(_,_)=>filter();filter();var selected=editing?.Tests.Select(t=>new TestLine{Name=t.Name,Price=t.Price,Modality=t.Modality}).ToList()??new List<TestLine>();var selectedGrid=GridView(selected.Select(x=>new{x.Name,x.Price}).ToList(),145);right.Children.Add(selectedGrid);void refresh()=>selectedGrid.ItemsSource=selected.Select(x=>new{x.Name,x.Price}).ToList();var add=Action("+ Add selected test",()=>{if(candidates.SelectedItem is TestDefinition t){selected.Add(new TestLine{Name=t.Name,Price=t.Price,Modality=LegacyImporter.Modality(t.Name)});refresh();}});right.Children.Add(add);var remove=Action("Remove last test",()=>{if(selected.Count>0){selected.RemoveAt(selected.Count-1);refresh();}});right.Children.Add(remove);
  var discount=Field(right,"Discount (Rs)",editing?.Discount.ToString()??"0");var received=Field(right,"Received (Rs)",editing?.Received.ToString()??"0");var calculations=Text("Gross: Rs 0 | Net: Rs 0 | Balance: Rs 0",13,true);right.Children.Add(calculations);void total(){var gross=selected.Sum(t=>t.Price);var net=Math.Max(0,gross-Dec(discount.Text));calculations.Text=$"Gross Rs {gross:N0} • Net Rs {net:N0} • Balance Rs {Math.Max(0,net-Dec(received.Text)):N0}";}discount.TextChanged+=(_,_)=>total();received.TextChanged+=(_,_)=>total();total();
  var actions=Row();actions.Children.Add(Action(editing is null?"Register patient":"Save all changes",()=>{if(string.IsNullOrWhiteSpace(name.Text)||selected.Count==0){Info("Patient name and at least one test are required.");return;}if(selected.Any(t=>t.Modality=="CT")&&string.IsNullOrWhiteSpace(mr.Text)){Info("CT examinations require a manual MR number.");return;}
   var p=editing??new Patient{Receipt=store.NextReceipt()};p.Name=CultureInfo.CurrentCulture.TextInfo.ToTitleCase(name.Text.Trim().ToLowerInvariant());p.Phone=phone.Text.Trim();p.Age=age.Text;p.Gender=gender.SelectedItem?.ToString()??"";p.Mr=mr.Text.Trim();p.ReferringDoctor=refdoc.SelectedItem?.ToString()??"";p.PerformingDoctor=perf.SelectedItem?.ToString()??"";p.Notes=clinical.Text;p.Tests=selected;p.Subtotal=selected.Sum(t=>t.Price);p.Discount=Math.Max(0,Dec(discount.Text));p.Received=Math.Max(0,Dec(received.Text));p.CreatedBy=current?.UserName??"";store.Put("patients",p.Id,p);notices.Evaluate();Info("Saved: "+p.Receipt);OpenPage("Patients & Receipts");},true));actions.Children.Add(Action("Cancel",()=>OpenPage("Patients & Receipts")));root.Children.Add(Card(actions));return root;
 }
 private FrameworkElement Patients(){var root=Column();var tool=Row();var query=new TextBox{Width=275};tool.Children.Add(query);var filt=new ComboBox{ItemsSource=new[]{"All","CT","X-Ray","Ultrasound"},SelectedIndex=0,Width=130};tool.Children.Add(filt);var archived=new CheckBox{Content="Show deleted archive",Margin=new Thickness(12,11,10,0)};tool.Children.Add(archived);root.Children.Add(Card(tool,"Find patients and receipts"));var grid=new DataGrid{Height=410,IsReadOnly=true,SelectionMode=DataGridSelectionMode.Single,AutoGenerateColumns=true};root.Children.Add(Card(grid));
  void refresh(){var ps=store.All<Patient>("patients").Where(x=>x.Deleted==archived.IsChecked);var term=query.Text.Trim();if(term.Length>0)ps=ps.Where(x=>string.Join(" ",x.Name,x.Phone,x.Mr,x.Receipt).Contains(term,StringComparison.OrdinalIgnoreCase));var type=filt.SelectedItem?.ToString()??"All";if(type!="All")ps=ps.Where(x=>x.Tests.Any(t=>t.Modality==type));grid.ItemsSource=ps.OrderByDescending(x=>x.Date).Select(x=>new{x.Receipt,x.Date,x.Name,x.Mr,x.Phone,Tests=string.Join(", ",x.Tests.Select(t=>t.Name)),x.Net,x.Received,x.Balance,Record=x}).ToList();}refresh();query.TextChanged+=(_,_)=>refresh();filt.SelectionChanged+=(_,_)=>refresh();archived.Checked+=(_,_)=>refresh();archived.Unchecked+=(_,_)=>refresh();
  Patient? selected()=>grid.SelectedItem is null?null:(Patient?)grid.SelectedItem.GetType().GetProperty("Record")?.GetValue(grid.SelectedItem);
  var controls=Row();controls.Children.Add(Action("Edit selected",()=>{var p=selected();if(p is not null)PageContent.Content=Reception(p);}));controls.Children.Add(Action("Print receipt",()=>{var p=selected();if(p is not null)PrintReceipt(p);}));controls.Children.Add(Action("Archive / restore",()=>{var p=selected();if(p is null||current?.Role!="Admin"){Info("Admin approval is required.");return;}p.Deleted=!p.Deleted;store.Put("patients",p.Id,p);refresh();}));root.Children.Add(Card(controls));return root;
 }
 private void PrintReceipt(Patient p){try{printer.Receipt(p,store.Settings);if(string.IsNullOrWhiteSpace(p.Phone))return;var raw=new string(p.Phone.Where(char.IsDigit).ToArray());if(raw.StartsWith("0"))raw="92"+raw[1..];var uri="whatsapp://send?phone="+Uri.EscapeDataString(raw)+"&text="+Uri.EscapeDataString($"Your receipt {p.Receipt} at {store.Settings.Name} has been prepared.");if(MessageBox.Show("Open WhatsApp Desktop with a prepared message?","MediLab X",MessageBoxButton.YesNo)==MessageBoxResult.Yes)Process.Start(new ProcessStartInfo(uri){UseShellExecute=true});}catch(Exception e){Error(e);}}
 private FrameworkElement Reports(){var root=Column();var panel=Column();var patients=store.All<Patient>("patients").Where(x=>!x.Deleted).OrderByDescending(x=>x.Date).ToList();var patient=Select(panel,"Patient receipt",patients.Select(p=>p.Receipt+" — "+p.Name),patients.FirstOrDefault() is { } first?first.Receipt+" — "+first.Name:null);var modality=Select(panel,"Modality",new[]{"CT","X-Ray","Ultrasound"});var findings=Field(panel,"Findings", "",8000);findings.Height=120;findings.AcceptsReturn=true;findings.TextWrapping=TextWrapping.Wrap;var impression=Field(panel,"Impression","",4000);impression.Height=86;impression.AcceptsReturn=true;impression.TextWrapping=TextWrapping.Wrap;var approval=Field(panel,"Pathologist / report approval");var heading=Check(panel,"With heading (for blank A4); uncheck for preprinted letterhead");var actions=Row();actions.Children.Add(Action("Save report",()=>{var p=patients.FirstOrDefault(x=>patient.SelectedItem?.ToString()?.StartsWith(x.Receipt+" — ")==true);if(p is null){Info("Select a patient first.");return;}var r=new Report{PatientId=p.Id,Date=Today,Modality=modality.SelectedItem?.ToString()??"CT",Findings=findings.Text,Impression=impression.Text,ApprovedBy=approval.Text,WithHeading=heading.IsChecked==true};SaveAndRefresh("reports",r.Id,r,"Radiology report saved.");},true));actions.Children.Add(Action("Print preview",()=>{var p=patients.FirstOrDefault(x=>patient.SelectedItem?.ToString()?.StartsWith(x.Receipt+" — ")==true);var r=new Report{PatientId=p?.Id??"",Modality=modality.SelectedItem?.ToString()??"CT",Findings=findings.Text,Impression=impression.Text,ApprovedBy=approval.Text,WithHeading=heading.IsChecked==true};printer.Report(p,r,store.Settings);}));panel.Children.Add(actions);root.Children.Add(Card(panel,"Radiology report editor"));root.Children.Add(Card(GridView(store.All<Report>("reports").Select(x=>new{x.Date,x.Modality,x.ApprovedBy,x.Findings,x.Impression}).ToList(),200),"Saved reports"));return root;
 }
